  add(refl, 'e', poly(mir(front).concat([[W + 60, hz], [-60, hz]])), dk ? 'rgba(14,28,46,0.7)' : 'rgba(112,140,178,0.55)');
  var tr = '', rt = ''; for (var x = -20; x < W + 20; x += 6 + rnd() * 8) { var th = 8 + rnd() * 16; tr += poly([[x - th * 0.28, hz + 2], [x, hz - th], [x + th * 0.28, hz + 2]]); rt += poly([[x - th * 0.28, hz], [x, hz + th * 0.8], [x + th * 0.28, hz]]); }
  if (ANIM) ANIM.trees = tr;
  add(mid, 'e', tr, dk ? '#081422' : '#4E6E7E'); add(refl, 'f', rt, dk ? 'rgba(6,14,24,0.7)' : 'rgba(70,100,120,0.45)');
  // Snowy shore in front
  var sy = H * (ph ? 0.83 : 0.84), sh = ridge(W, sy, [[10, 160, 1.2], [5, 60, 0.4]], 10), sh2 = ridge(W, sy + (ph ? 40 : 50), [[12, 200, 2.6], [5, 70, 1.4]], 10);
  var sheen = ''; spread(0, hz + 12, W, sy - hz - 20, 150, 26, rnd, 1).forEach(function (c) { if (c.q < 0.5) { if (ANIM) (ANIM.sheen = ANIM.sheen || []).push({x: c.x, y: c.y, w: 20 + c.r * 60, k: c.k}); sheen += seg(c.x, c.y, c.x + 20 + c.r * 60, c.y); } });
  if (!ANIM) stk(mid, 's', sheen, dk ? 'rgba(150,230,210,0.22)' : 'rgba(255,255,255,0.6)', 1.5);
  add(near, 'a', below(sh, H + 10), dk ? '#1A2B40' : '#E6EEF8'); add(near, 'b', below(sh2, H + 10), dk ? '#22364E' : '#F7FAFE');
  stk(mid, 't', pline(sh.map(function (p) { return [p[0], p[1] - 1]; })), dk ? 'rgba(160,210,255,0.35)' : 'rgba(255,255,255,0.9)', 2);
  // Pines on both sides and a cabin
