  var lowerEdge = []; for (i = 0; i <= 10; i++) { var xx = lerp(top[top.length - 1][0], top[0][0], i / 10); lowerEdge.push([xx, sl + (i % 2 ? 10 : -4) * (ph ? 0.7 : 1)]); }
