  for (x = -10; x < W + 10; x += (ph ? 22 : 30) + rnd() * 40) { if (Math.abs(x - W * (ph ? 0.2 : 0.14)) < 26) continue; var y = b2_y(hz, sw, x), r = (ph ? 9 : 12) + rnd() * 9; tk += rect(x - 1.5, y - r, 3, r); var blob = circ(x, y - r * 1.4, r) + circ(x - r * 0.8, y - r * 1.0, r * 0.7) + circ(x + r * 0.8, y - r * 1.05, r * 0.75); if (rnd() < 0.5) bl1 += blob; else bl2 += blob; rf += ell(x, y + r * 1.2, r * 1.3, r * 0.5); }
  add(mid, 'b', tk, dk ? '#2A1624' : '#7A5A62');
  add(mid, 'c', bl1, dk ? '#A0506E' : '#F4B3C8'); add(mid, 'd', bl2, dk ? '#C06888' : '#F8CBD8');
  add(mid, 'e', rf, dk ? 'rgba(170,80,120,0.25)' : 'rgba(240,160,190,0.3)');
