  for (i = 0; i < 4; i++) { var ry = gy - 14 * gs - i * 17 * gs, rw = (30 - i * 5) * gs; pg += poly([[gx - rw, ry], [gx - rw * 0.6, ry - 6 * gs], [gx + rw * 0.6, ry - 6 * gs], [gx + rw, ry], [gx + rw * 0.8, ry + 3 * gs], [gx - rw * 0.8, ry + 3 * gs]]) + rect(gx - rw * 0.5, ry + 2, rw, 13 * gs); }
  pg += rect(gx - 1.5 * gs, gy - 96 * gs, 3 * gs, 28 * gs);
