  add(refl, 'd', sticks[0], dk ? '#D8C8E6' : '#FFFFFF'); add(refl, 'e', disc[0][0], dcol[0]); add(refl, 'f', disc[0][1], dcol[1]); add(refl, 'g', disc[0][2], dcol[2]); stk(refl, 's', sw[0], 'rgba(255,255,255,0.7)', 1.6 * u);
