  var stand = ell(kx, cty - 10 * u, 44 * u, 8 * u) + rect(kx - 8 * u, ky + 6 * u, 16 * u, cty - 10 * u - ky - 6 * u) + ell(kx, ky + 4 * u, kw * 0.66, 11 * u);
