  if (!ANIM) for (var d = 0; d < 7; d++) { var dx = kx - kw / 2 + 10 * u + d * (kw - 20 * u) / 6; cream += circ(dx, topY - 4 * u, 8 * u) + rrect(dx - 3.5 * u, topY, 7 * u, (8 + (d * 7 % 5) * 4) * u, 3.5 * u); }
