    if (c.k < 0.12) return; ob.push([c.x, c.y, rr]);
    if (ANIM) (ANIM.orbs = ANIM.orbs || []).push({x: c.x, y: c.y, r: rr, c: cols[ci]}); else { add(mid, keys[ci], circ(c.x, c.y, rr), cols[ci]); rim += circ(c.x, c.y, rr - 0.6); } hi += circ(c.x - rr * 0.25, c.y - rr * 0.25, rr * 0.45);
