  for (x = -10; x < W + 10; x += ph ? 3.5 : 4.5) { var hh = gh * (0.3 + 0.7 * rnd()) * (0.7 + 0.3 * Math.sin(x / 70 + 1)); var bl = b4_blade(x + rnd() * 4, H + 4, hh, 5 + rnd() * 5, (rnd() - 0.4) * hh * 0.35); if (rnd() < 0.5) gb += bl; else gf += bl; }
  add(near, 'a', gb, dk ? '#2C2854' : '#9A96C8'); add(near, 'b', gf, dk ? '#1E1B3E' : '#7B77AE');
