    if (ph) top = gy - H * 0.45 + bi * H * 0.06;
    add(far, fk[bi % 3], rect(xs, top, bw, gy - top + 2), fac[bi % 3]); occ.push([xs - 4, top - 6, bw + 8]);
    trim += rect(xs - 4, top - 6, bw + 8, 8) + rect(xs, gy - shopH - 10, bw, 6);
    // upper windows
