    shopLit += rrect(sx0, sy0, sw, shopH - 24, 4); trim += rect(sx0 - 3, gy - 12, sw + 6, 5);
    door += rrect(sx0 + sw + bw * 0.06, sy0 + 6, bw * 0.16, shopH - 20, 3);
    // neon signs over each shop
