  mul += rect(X - fr, Y - fr, fr, wh + fr * 2) + rect(X + ww, Y - fr, fr, wh + fr * 2) + rect(X - fr, Y - fr, ww + 2 * fr, fr) + rect(X - fr, Y + wh, ww + 2 * fr, fr);
