  sh.forEach(function (s, i) { shelf += rect(s[0], s[1], s[2], 7); var bk = b5_books(s[0] + 8, s[1], s[2] * 0.45, ph ? 34 : 44, rnd); for (var k = 0; k < 3; k++) books[k] += bk[k]; var px = s[0] + s[2] * (i % 2 ? 0.62 : 0.78); pots += b5_pot(px, s[1], 22, 20); lv += b5_plant(px, s[1] - 18, 30, rnd, 6, 150); if (i === 1) { var vp = [[px + 9, s[1] - 19], [px + 11.5, s[1] - 10], [px + 9, s[1] + 3]]; for (var q = 0; q < 5; q++) { lv2 += leaf(px + 6 + q * 3, s[1] + 12 + q * 16, 12, 5, 70 + (q % 2) * 40); vp.push([px + 6 + q * 3, s[1] + 12 + q * 16]); } lv2 += b5_tube(vp, 1.8, 1.2); } });
