  fr.forEach(function (f) { frames += rect(f[0], f[1], f[2], f[3]); pic += rect(f[0] + 7, f[1] + 7, f[2] - 14, f[3] - 14); });
  add(mid, 'e', shelf + frames, dk ? '#5A3C30' : '#A8725A');
