  var strand = b5_strand(cx + cs * 0.62, cy - cs * 0.06, -30, H - (ph ? 104 : 50), ph ? 1 : 3, ph ? 16 : 24, rnd, ph ? 0.79 : 0, ph ? 0.84 : 0); if (ph) { rnd(); rnd(); }
  var strand2 = 'M' + PT(cx + cs * 0.84, cy - cs * 0.06) + ' C' + PT(cx + cs * 1.2, cy + 10) + ' ' + PT(W * 0.95, H - (ph ? 110 : 60)) + ' ' + PT(W + 30, H - (ph ? 90 : 40)) + ' ';
