    var tie0 = [cx + cs * 0.62, cy - cs * 0.06], c1s = [lerp(tie0[0], -30, 0.2), H - (ph ? 104 : 50) + (ph ? 16 : 24) * 2], tdl = Math.hypot(tie0[0] - c1s[0], tie0[1] - c1s[1]);
