  var rodY = w.y - R.fr * 2.5 - 2, wire = [[lx0 - 4, rodY]]; for (t = 0; t <= 1.0001; t += 0.01) wire.push([lerp(lx0, lx1, t), w.y - R.fr * 1.2 + Math.sin(t * Math.PI * 3) * 7 + 12]); wire.push([lx1 + 4, rodY]);
