  for (i = 1; i < 5; i++) { var yy = lerp(aT + chh * 0.05, fB - chh * 0.02, i / 5), xl = yy < sT ? tL + ch.arm * 0.1 : tL + 2; tstr += seg(xl, yy, yy < sT ? chx + ch.arm * 1.05 : tR, yy + 1); }
