// ---- scenes_b6.js
// ---- batch b6: painting (Art Studio), gardening (Garden Plot), photography (Photo Walk), gaming (Game Night)

// Smooth Catmull-Rom curve through points.
function b6_cr(P, n) { var out = []; for (var i = 0; i < P.length - 1; i++) { var p0 = P[Math.max(0, i - 1)], p1 = P[i], p2 = P[i + 1], p3 = P[Math.min(P.length - 1, i + 2)]; for (var k = 0; k < n; k++) { var t = k / n, t2 = t * t, t3 = t2 * t, o = []; for (var a = 0; a < 2; a++) o.push(0.5 * (2 * p1[a] + (-p0[a] + p2[a]) * t + (2 * p0[a] - 5 * p1[a] + 4 * p2[a] - p3[a]) * t2 + (-p0[a] + 3 * p1[a] - 3 * p2[a] + p3[a]) * t3)); out.push(o); } } out.push(P[P.length - 1]); return out; }
// A band of width 2*hw along a polyline.
function b6_band(pts, hw) { var L = [], R = []; for (var i = 0; i < pts.length; i++) { var a = pts[Math.max(0, i - 1)], b = pts[Math.min(pts.length - 1, i + 1)], dx = b[0] - a[0], dy = b[1] - a[1], l = Math.sqrt(dx * dx + dy * dy) || 1, nx = -dy / l, ny = dx / l, w = typeof hw === 'function' ? hw(i / (pts.length - 1)) : hw; L.push([pts[i][0] + nx * w, pts[i][1] + ny * w]); R.unshift([pts[i][0] - nx * w, pts[i][1] - ny * w]); } return poly(L.concat(R)); }
function b6_bandP(pts, hw) { var L = [], R = []; for (var i = 0; i < pts.length; i++) { var a = pts[Math.max(0, i - 1)], b = pts[Math.min(pts.length - 1, i + 1)], dx = b[0] - a[0], dy = b[1] - a[1], l = Math.sqrt(dx * dx + dy * dy) || 1, nx = -dy / l, ny = dx / l; L.push([pts[i][0] + nx * hw, pts[i][1] + ny * hw]); R.unshift([pts[i][0] - nx * hw, pts[i][1] - ny * hw]); } return L.concat(R); }
// Heart centred at x,y, about 2*s wide.
function b6_heart(x, y, s) { var p = []; for (var i = 0; i < 30; i++) { var t = i / 30 * Math.PI * 2, st = Math.sin(t); p.push([x + s * st * st * st, y - s * (13 * Math.cos(t) - 5 * Math.cos(2 * t) - 2 * Math.cos(3 * t) - Math.cos(4 * t)) / 16]); } return poly(p); }
// Soft rounded five-point star.
function b6_star(x, y, R, rot) { var p = []; for (var i = 0; i < 60; i++) { var t = i / 60 * Math.PI * 2, r = R * (0.5 + 0.5 * Math.pow((1 + Math.cos(5 * t)) / 2, 1.6)); p.push([x + r * Math.cos(t - Math.PI / 2 + (rot || 0)), y + r * Math.sin(t - Math.PI / 2 + (rot || 0))]); } return poly(p); }
