// Wooden artist palette (kidney shape with a thumb hole), flattened by sy, rotated.
function b6_palette(cx, cy, rx, ry, ang) { var o = [], h = []; for (var i = 0; i < 40; i++) { var t = i / 40 * Math.PI * 2, d = t - 0.35; d = Math.atan2(Math.sin(d), Math.cos(d)); var bite = 1 - 0.26 * Math.exp(-d * d / 0.06); o.push([rx * Math.cos(t) * bite, ry * Math.sin(t) * bite]); } for (i = 0; i < 18; i++) { var u = -i / 18 * Math.PI * 2; h.push([rx * 0.52 + rx * 0.11 * Math.cos(u), ry * 0.2 + ry * 0.2 * Math.sin(u)]); } return poly(rotp(o, cx, cy, ang)) + poly(rotp(h, cx, cy, ang)); }
