  pt('bl', ell(pcx - prx * 0.1, pcy + pry * 0.1, prx * 0.12, pry * 0.2)); pt('ye', ell(pcx + prx * 0.08, pcy + pry * 0.15, prx * 0.08, pry * 0.15));
  // brushes lying on the table and standing in a jar
