  handles += seg(pcx - prx * 0.4, tt - 4, pcx + prx * 0.7, tt - 12);
  pt('bl', leaf(pcx - prx * 0.4, tt - 4, 16, 3.5, 176));
  var bangs = [-104, -90, -76, -84];
  bangs.forEach(function (a, i) { var r = a * Math.PI / 180, l = (ph ? 58 : 80) + i * 6, x2 = jx + Math.cos(r) * l, y2 = jy - 30 + Math.sin(r) * l, x1 = jx + (i - 1.5) * 4 + (jrim - (jy - 20)) * Math.cos(r) / Math.sin(r);
    if (ANIM && i === 2) { ANIM.brush = {x1: x1, y1: jrim, x2: x2, y2: y2, tl: ph ? 12 : 16, tw: ph ? 3 : 4, col: P.bl, hc: dk ? '#7E88A8' : '#34466E', hw: ph ? 3 : 4}; return; }
    handles += seg(x1, jrim, x2, y2); pt(['ro', 'ye', 'bl', 'gr'][i], leaf(x2, y2, ph ? 12 : 16, ph ? 3 : 4, a)); });
  stk(near, 's', handles, dk ? '#7E88A8' : '#34466E', ph ? 3 : 4);
  add(near, 'h', rrect(jx - (ph ? 16 : 20), jy - (ph ? 44 : 56), ph ? 32 : 40, ph ? 44 : 56, 7), dk ? '#B8834E' : '#9FB7C9');
  // easel with a painting in progress
  var ex = ph ? W * 0.74 : W * 0.86, cw = ph ? 150 : 230, ch = ph ? 124 : 180, ctop = ph ? fl - 212 : fl - 300, ey = ctop + ch;
  var legs = poly([[ex - 4, ctop - 34], [ex + 4, ctop - 34], [ex - cw * 0.4 + 4, fl + (ph ? 100 : 130)], [ex - cw * 0.4 - 5, fl + (ph ? 100 : 130)]]) + poly([[ex - 4, ctop - 34], [ex + 4, ctop - 34], [ex + cw * 0.4 + 5, fl + (ph ? 100 : 130)], [ex + cw * 0.4 - 4, fl + (ph ? 100 : 130)]]) + poly([[ex - 3, ctop - 20], [ex + 3, ctop - 20], [ex + cw * 0.12 + 3, fl + 50], [ex + cw * 0.12 - 3, fl + 50]]) + rect(ex - cw * 0.56, ey, cw * 1.12, 10) + rect(ex - 7, ctop - 14, 14, 18);
  add(mid, 'a', ell(ex, fl + (ph ? 96 : 124), cw * 0.95, ph ? 26 : 36), dk ? '#262C4C' : '#C7D2E4');
  add(near, 'a', legs, wood);
