  add(near, 'd', dl, C.d); add(near, 'e', el, C.e); add(near, 'f', fl1, C.f); add(near, 'h', fc, C.h);
  add(near, 'c', '', C.rim); add(near, 'b', '', C.tc); add(far, 'g', '', dk ? 'rgba(0,0,0,0.5)' : 'rgba(60,40,20,0.3)');
  // night: string lights along the middle rail
