  var gc = ['rgba(255,80,100,0.45)', 'rgba(255,200,90,0.45)', 'rgba(80,220,210,0.4)', 'rgba(170,130,255,0.45)', 'rgba(255,150,210,0.4)', 'rgba(220,230,255,0.35)'];
