  for (var s = 0; s < 7; s++) { var top = [], bot = []; for (var xx = -20; xx <= W + 20; xx += 12) { top.push([xx, by(xx) + s * sw]); bot.unshift([xx, by(xx) + (s + 1) * sw + 0.6]); } var pp = poly(top.concat(bot)); if (s % 2 === 0) red += pp; else wht += pp; }
