  var jl = ph ? [[0.265, 0.86, 48], [0.6, 0.875, 58], [0.875, 0.83, 35]] : [[0.62, 0.86, 70], [0.78, 0.88, 88], [0.93, 0.84, 56]];
  var little = ph ? [[0.065, 0.78, 19], [0.44, 0.75, 14]] : [[0.22, 0.86, 26], [0.36, 0.9, 20], [0.48, 0.83, 18]];
  var dark = '', lite = '', face = '', stem = '', vine = '';
