  var sky = dk ? 'radial-gradient(70% 45% at 65% 58%,rgba(90,120,200,0.35),rgba(0,0,0,0) 70%),linear-gradient(180deg,#0A1124 0%,#132247 ' + P(hy * 0.7) + '%,#2A3D70 ' + P(hy) + '%,#1A2544 100%)' : 'radial-gradient(70% 40% at 65% 55%,rgba(255,236,214,0.8),rgba(255,255,255,0) 70%),linear-gradient(180deg,#9FB5DD 0%,#C4D3EC ' + P(hy * 0.7) + '%,#E6EAF4 ' + P(hy) + '%,#DCE4F2 100%)';
