  var snow = ''; if (ANIM) ANIM.snow = []; spread(cw, 0, W - 2 * cw, sy, ph ? 30 : 40, ph ? 30 : 40, rnd, 1).forEach(function (c) { if (c.q < 0.55) { if (ANIM) ANIM.snow.push({x: c.x, y: c.y, r: 0.9 + c.r * 1.9}); else snow += circ(c.x, c.y, 0.9 + c.r * 1.9); } });
  if (ANIM) ANIM.snowC = dk ? 'rgba(235,242,255,0.85)' : 'rgba(255,255,255,0.95)';
