  add(M, 'h', b8_ellc(x, cy + 53 * s, 3 * s, 3 * s) + poly([[x - 3 * s, cy + 55 * s], [x + 3 * s, cy + 55 * s], [x + 6 * s, cy + 76 * s], [x - 6 * s, cy + 76 * s]]), '');
  add(G, 'c', circ(x, cy, 50 * s), '');
