  add(bg, 'a', fh, dk ? '#3A1832' : '#E2B9B4'); add(bg, 'b', nh, dk ? '#2A1026' : '#CFA0A2');
  add(bg, 'c', wins, dk ? '#FFB65A' : '#F6CE8C'); add(bg, 'd', dots, dk ? '#FFD27A' : '#F2B85A'); stk(bg, 's', wires, dk ? 'rgba(20,6,14,0.7)' : 'rgba(150,100,100,0.5)', 0.8);
