  add(N, 'a', ell(x, cy, r, ry), ''); add(N, 'b', ell(x - (dk ? 0 : r * 0.28), cy - ry * 0.05, r * (dk ? 0.55 : 0.26), ry * (dk ? 0.72 : 0.62)), '');
