  add(N, 'd', poly([[x - r * 0.08, cy + ry + r * 0.42], [x + r * 0.08, cy + ry + r * 0.42], [x + r * 0.17, cy + ry + r * 1.08], [x - r * 0.17, cy + ry + r * 1.08]]), '');
