  var m3 = ridge(W, wy - H * 0.022, [[H * 0.01, 150, 1.1], [4, 44, 0.3]], 10);
  add(bg, 'a', below(m1, wy + 2), dk ? '#3C1C20' : '#EBCFC6');
  var mist = ''; spread(0, wy - H * 0.2, W, H * 0.16, 260, 70, rnd, 0.8).forEach(function (c) { mist += ell(c.x, c.y, 140 + c.r * 90, 12 + c.k * 8); });
  add(bg, 'b', mist, dk ? 'rgba(110,50,50,0.28)' : 'rgba(255,246,240,0.7)');
  add(bg, 'c', below(m2, wy + 2), dk ? '#2E1418' : '#DDB0A6');
  add(bg, 'e', below(m3, wy + 2), dk ? '#221012' : '#C8948A');
