  for (var k = 0; k < 5; k++) { var w = pw * (1 - k * 0.14), yb = pb - k * pw * 0.72, hgt = pw * 0.44; pgs += rect(px - w * 0.62, yb - hgt, w * 1.24, hgt) + poly([[px - w * 0.55, yb - hgt - pw * 0.28], [px + w * 0.55, yb - hgt - pw * 0.28], [px + w * 1.15, yb - hgt - 1], [px + w * 0.8, yb - hgt + 2], [px - w * 0.8, yb - hgt + 2], [px - w * 1.15, yb - hgt - 1]]); }
