  if (dk) spread(0, 0, W, wy * 0.7, 48, 48, rnd, 1).forEach(function (c) { var mi = Math.max(0, Math.min(m1.length - 1, Math.round((c.x + 60) / 8))); if (c.q < 0.3 && c.y < m1[mi][1] - 8 && c.y < wy - H * 0.2 - 30) add(mid, 'b', circ(c.x, c.y, 0.6 + c.r * 0.7), 'rgba(255,230,210,0.75)'); });
  // lantern strings across the top
