  if (ANIM) ANIM.lanC = LC;
  near.a.c = LC.a; near.b.c = LC.b; near.c.c = LC.c; near.d.c = LC.d; near.s.c = LC.s; near.s.w = 1.2; mid.s.c = LC.m; mid.s.w = 1.2; far.b.c = LC.g;
  var rows = ph ? [[-20, 8, W + 20, 14, 40, 78, 26], [-20, H * 0.42, W + 20, H * 0.4, 44, 95, 25]] : [[-20, 6, W + 30, 14, 70, 130, 34], [W * 0.46, lerp(6, 14, (W * 0.46 + 20) / (W + 50)) + 70 * 4 * ((W * 0.46 + 20) / (W + 50)) * (1 - (W * 0.46 + 20) / (W + 50)), W + 30, H * 0.2, 60, 150, 36]];  // the 2nd string starts on the 1st (it used to begin in mid-air)
  rows.forEach(function (rw, ri) { var pts = b8_cat(rw[0], rw[1], rw[2], rw[3], rw[4], 60); stk(mid, 's', pline(pts), '', 0);
    var n = Math.floor((rw[2] - rw[0]) / rw[5]); for (var i = 0; i < n; i++) { var t = (i + 0.5) / n, x = lerp(rw[0], rw[2], t), y = lerp(rw[1], rw[3], t) + rw[4] * 4 * t * (1 - t), drop = 8 + ((i * 7 + ri * 3) % 5) * (ph ? 7 : 12), r = rw[6] * (0.8 + ((i * 3 + ri) % 4) * 0.1);
      if (ANIM) { var TL = Lay(0), TM = Lay(0), TG = Lay(0); var lcy = b8_lan(TL, TM, TG, 0, drop, r, dk); (ANIM.lan = ANIM.lan || []).push({x: x, y: y, cy: lcy, r: r, L: TL, M: TM}); continue; }
      stk(mid, 's', seg(x, y, x, y + drop), '', 0); b8_lan(near, mid, far, x, y + drop, r, dk); } });
  // plum blossom branch along the bottom
