  near.e.c = BP.e; near.f.c = BP.f; near.g.c = BP.g; near.h.c = BP.h; near.t.c = BP.t; near.t.w = 0.9;
  var seg0 = ph ? 34 : 58, bx = -30, byy = H * (ph ? 0.87 : 0.95), ang = -10, main = [[bx, byy]], nseg = ph ? 12 : 16;
  for (var i = 0; i < nseg; i++) { ang = (ph ? -16 : -11) + (i % 2 ? 13 : -13) + (rnd() - 0.5) * 10; bx += Math.cos(ang * Math.PI / 180) * seg0; byy += Math.sin(ang * Math.PI / 180) * seg0; main.push([bx, byy]); }
  add(near, 'e', b8_taper(main, ph ? 16 : 22, 2.5), '');
