    var ribbon = st === 1, cw = st === 3 ? (ph ? 16 : 22) : 9, gap = st === 3 ? (ph ? 9 : 12) : 5, rows = st === 3 ? 22 : 13, wh = st === 3 ? 12 : 7;
    var ncol = Math.max(1, Math.floor((w - 10 + gap) / (cw + gap))), mx0 = x + (w - (ncol * cw + (ncol - 1) * gap)) / 2;
