  if (ANIM) { ANIM.mask = mask; ANIM.wins = list; ANIM.tick = tick; ANIM.winC = [C.win, C.lit]; ANIM.gy = gy; ANIM.items = m1_TICK; ANIM.beacons = bea; ANIM.towers = tw; }
  else if (tick) { var tb = ''; for (var q = tick.x + 8; q < tick.x + tick.w - 20; q += 46) tb += rrect(q, tick.y + tick.h * 0.38, 30 + rnd() * 8, tick.h * 0.24, 2); stk(mid, 't', tb, '#6EE29A', 1); }
