    wing: rotEll(X(-2.6), Y(-8), 7.4 * s, 3.8 * s, -8 * d), neck: ell(X(6.6), Y(-10.6), 2.8 * s, 2.3 * s), legs: rect(X(-0.5) - 0.6 * s, Y(-2.4), 1.2 * s, 2.6 * s) + rect(X(2.2) - 0.6 * s, Y(-2.4), 1.2 * s, 2.6 * s),
