  var clouds = ph ? [[0.78, 0.07, 0.7], [0.16, 0.25, 0.6], [0.88, 0.31, 0.55]] : [[0.36, 0.08, 0.9], [0.9, 0.12, 0.8], [0.06, 0.34, 0.6], [0.98, 0.36, 0.7], [0.5, 0.22, 0.55]];
