  var colH = ph ? H * 0.125 : H * 0.2, colTop = yS - colH, colW = pw * (ph ? 0.085 : 0.07), entH = ph ? 30 : 40, entTop = colTop - entH, pedH = pw * 0.16;
  var bodyW = pw * (ph ? 1.3 : 1.62), bodyTop = entTop + entH * 0.4, drumW = pw * 0.42, drumH = pw * 0.12, drumBase = entTop - pedH * 0.45, drumTop = drumBase - drumH, domeR = drumW * 0.47;
