  shade += rect(x0 - 4, entTop + entH * 0.3, pw + 8, entH * 0.12) + poly([[x0 + 10, entTop - 4], [cx, entTop - pedH + 12], [x1 - 10, entTop - 4]]) + rect(x0 - 4, entTop + entH * 0.42, pw + 8, 3);
