  function joint(a, b, t) { var ta = tie(a), tb = tie(b), s = Math.max(a.s, b.s), ex = (ta[0] + tb[0]) / 2, ey = Math.max(ta[1] + a.s * 1.65, tb[1] + b.s * 1.65), sw = Math.sin(t * 0.35 + a.ph - 0.9) * 7; return [ex, ey, ex + sw * 0.3, ey + s * 1.4]; }
