    var f = [sx - 8, sy + s * 1.2, sx + 2 + sw * 0.4, sy + s * 2.2, sx + 12 + sw * 0.7, sy + s * 3.2, sx - 2 + sw, sy + s * 4];
    if (k > 0) { var j = [sx + (J[0] - sx) * 0.2 - 6, sy + (J[1] - sy) * 0.5, J[0], J[1], (J[0] + J[2]) / 2, (J[1] + J[3]) / 2, J[2], J[3]]; for (var i = 0; i < 8; i++) f[i] += (j[i] - f[i]) * k; }
