// ---- Study Fields batch m5 engines: observatory, ruins, valley, sketchcity
function m5_ease(u) { u = Math.max(0, Math.min(1, u)); return u * u * (3 - 2 * u); }
function m5_env(T, a, b, c, d) { if (T < a || T > d) return 0; if (T < b) return m5_ease((T - a) / (b - a)); if (T <= c) return 1; return 1 - m5_ease((T - c) / (d - c)); }
var m5_gc = null;
function m5_ctx() { return m5_gc || (m5_gc = document.createElement('canvas').getContext('2d')); }
// radial glow centred on 0,0 that fades to transparent
function m5_rg(col, r, mid) { var g = m5_ctx().createRadialGradient(0, 0, 0, 0, 0, r); g.addColorStop(0, col); if (mid) g.addColorStop(mid[0], col.replace(/[\d.]+\)$/, mid[1] + ')')); g.addColorStop(1, col.replace(/[\d.]+\)$/, '0)')); return g; }
function m5_P(pts) { var p = new Path2D(); pts.forEach(function (q, i) { if (i) p.lineTo(q[0], q[1]); else p.moveTo(q[0], q[1]); }); p.closePath(); return p; }
function m5_dot(c, g, x, y, r, a) { if (a <= 0.003) return; c.save(); c.globalAlpha = a; c.translate(x, y); c.scale(r, r); c.fillStyle = g; c.beginPath(); c.arc(0, 0, 1, 0, 7); c.fill(); c.restore(); }

// ---------- little characters (kawaii-simple: round shapes, dot eyes, blush) ----------
var m5_INK = '#3A2A3A', m5_BLUSH = 'rgba(255,120,150,0.45)';
function m5_eyes(c, x, y, gap, r, blink, happy) { c.fillStyle = m5_INK; c.strokeStyle = m5_INK; if (happy) { c.lineWidth = r * 0.9; c.lineCap = 'round'; c.beginPath(); c.arc(x - gap, y + r * 0.6, r * 1.3, Math.PI * 1.15, Math.PI * 1.85); c.moveTo(x + gap + r * 1.3 * Math.cos(Math.PI * 1.15), y + r * 0.6 + r * 1.3 * Math.sin(Math.PI * 1.15)); c.arc(x + gap, y + r * 0.6, r * 1.3, Math.PI * 1.15, Math.PI * 1.85); c.stroke(); return; }
  if (blink < 0.25) { c.lineWidth = r * 0.8; c.lineCap = 'round'; c.beginPath(); c.moveTo(x - gap - r, y); c.lineTo(x - gap + r, y); c.moveTo(x + gap - r, y); c.lineTo(x + gap + r, y); c.stroke(); return; }
  c.beginPath(); c.ellipse(x - gap, y, r, r * blink, 0, 0, 7); c.ellipse(x + gap, y, r, r * blink, 0, 0, 7); c.fill(); c.fillStyle = '#FFFFFF'; c.beginPath(); c.arc(x - gap + r * 0.35, y - r * 0.35, r * 0.35, 0, 7); c.arc(x + gap + r * 0.35, y - r * 0.35, r * 0.35, 0, 7); c.fill(); }
function m5_cheeks(c, x, y, gap, r) { c.fillStyle = m5_BLUSH; c.beginPath(); c.ellipse(x - gap, y, r, r * 0.6, 0, 0, 7); c.ellipse(x + gap, y, r, r * 0.6, 0, 0, 7); c.fill(); }
function m5_smile(c, x, y, r, lw) { c.strokeStyle = m5_INK; c.lineWidth = lw; c.lineCap = 'round'; c.beginPath(); c.arc(x, y - r * 0.4, r, Math.PI * 0.2, Math.PI * 0.8); c.stroke(); }
// a face on any round object: closed sleepy eyes or open ones
function m5_face(c, x, y, r, sleep, blink, big) { if (sleep) { c.strokeStyle = m5_INK; c.lineWidth = Math.max(1, r * 0.07); c.lineCap = 'round'; c.beginPath(); c.arc(x - r * 0.32, y - r * 0.08, r * 0.14, Math.PI * 0.1, Math.PI * 0.9); c.moveTo(x + r * 0.46, y - r * 0.08 + r * 0.14 * Math.sin(Math.PI * 0.1)); c.arc(x + r * 0.32, y - r * 0.08, r * 0.14, Math.PI * 0.1, Math.PI * 0.9); c.stroke(); }
  else m5_eyes(c, x, y - r * 0.08, r * 0.32, r * 0.1, blink, false);
  m5_cheeks(c, x, y + r * 0.18, r * 0.52, r * 0.14); m5_smile(c, x, y + r * 0.2, r * (big ? 0.2 : 0.12), Math.max(1, r * 0.06)); }
function m5_blinkAt(t, seed) { var u = (t * 0.31 + seed * 3.7) % 4.3; return u < 0.12 ? Math.abs(u - 0.06) / 0.06 : 1; }
// sitting fox facing right; look: head tilt (radians, negative looks up), wag: tail swing, hop: lift
function m5_fox(c, x, y, s, t, look, wag, hop, happy) {
  var o = '#F2894E', w = '#FFF4E6', d = '#5A3A3A'; c.save(); c.translate(x, y - hop); c.scale(s, s);
  c.save(); c.translate(-6, -5); c.rotate(-0.6 + wag); c.fillStyle = o; c.beginPath(); c.ellipse(-12, 0, 14, 7, 0, 0, 7); c.fill(); c.fillStyle = w; c.beginPath(); c.ellipse(-22, 0, 5.5, 5, 0, 0, 7); c.fill(); c.restore();
  c.fillStyle = o; c.beginPath(); c.ellipse(0, -12, 10, 13, 0, 0, 7); c.fill(); c.fillStyle = w; c.beginPath(); c.ellipse(4, -11, 5, 8, 0, 0, 7); c.fill();
  c.fillStyle = w; c.beginPath(); c.ellipse(-4, -0.5, 4, 2.2, 0, 0, 7); c.ellipse(5, -0.5, 4, 2.2, 0, 0, 7); c.fill();
  c.save(); c.translate(3, -26); c.rotate(look);
  c.fillStyle = o; c.beginPath(); c.moveTo(-8, -4); c.lineTo(-6, -15); c.lineTo(0, -7); c.moveTo(2, -7); c.lineTo(8, -15); c.lineTo(9, -3); c.fill(); c.fillStyle = d; c.beginPath(); c.moveTo(-6.6, -11); c.lineTo(-6, -15); c.lineTo(-4.4, -12); c.moveTo(6.6, -12); c.lineTo(8, -15); c.lineTo(8.4, -11.5); c.fill();
  c.fillStyle = o; c.beginPath(); c.arc(0, 0, 9, 0, 7); c.fill(); c.fillStyle = w; c.beginPath(); c.moveTo(1, 1); c.quadraticCurveTo(10, -2, 15, 1.5); c.quadraticCurveTo(8, 7.5, 1, 6); c.fill();
  c.fillStyle = d; c.beginPath(); c.arc(15, 1.4, 1.6, 0, 7); c.fill();
  m5_eyes(c, 4, -2, 0.001, 1.5, happy ? 1 : m5_blinkAt(t, 2), happy); c.fillStyle = m5_BLUSH; c.beginPath(); c.ellipse(5, 3, 2.6, 1.6, 0, 0, 7); c.fill();
  c.restore(); c.restore(); }
// bunny sitting facing left or right (dir)
function m5_bunny(c, x, y, s, dir, t, hop, ear, col) {
  c.save(); c.translate(x, y - hop); c.scale(s * dir, s); var b = col || '#FFF8F2', pk = '#FFB3C6';
  c.fillStyle = b; c.beginPath(); c.ellipse(0, -7, 9, 7.5, 0, 0, 7); c.fill(); c.beginPath(); c.arc(-9, -8, 3.2, 0, 7); c.fill();
  c.save(); c.translate(6, -16); c.fillStyle = b; [[-2.5, -0.15 + ear], [2, 0.2 - ear * 0.6]].forEach(function (e) { c.save(); c.translate(e[0], -4); c.rotate(e[1]); c.fillStyle = b; c.beginPath(); c.ellipse(0, -7, 2.6, 7.5, 0, 0, 7); c.fill(); c.fillStyle = pk; c.beginPath(); c.ellipse(0, -7, 1.2, 5.5, 0, 0, 7); c.fill(); c.restore(); });
  c.fillStyle = b; c.beginPath(); c.arc(0, 0, 6.5, 0, 7); c.fill(); c.fillStyle = m5_INK; c.beginPath(); c.arc(2.6, -1, 1.1, 0, 7); c.fill(); c.fillStyle = pk; c.beginPath(); c.arc(6.2, 1, 1, 0, 7); c.fill(); c.fillStyle = m5_BLUSH; c.beginPath(); c.ellipse(2.4, 2.4, 1.8, 1.1, 0, 0, 7); c.fill(); c.restore();
  c.restore(); }
// owl perched: flap 0..1 opens the wings
function m5_owl(c, x, y, s, t, flap, look) {
  c.save(); c.translate(x, y); c.scale(s, s); var b = '#B98A6A', bl = '#F6E3C6';
  [[-1, 1], [1, 1]].forEach(function (q) { c.save(); c.translate(q[0] * 7, -9); c.rotate(q[0] * (0.2 + flap * 1.1)); c.fillStyle = '#9C6E50'; c.beginPath(); c.ellipse(q[0] * 2, 2, 3.2, 7, 0, 0, 7); c.fill(); c.restore(); });
  c.fillStyle = b; c.beginPath(); c.ellipse(0, -9, 8, 10, 0, 0, 7); c.fill(); c.beginPath(); c.moveTo(-7, -15); c.lineTo(-6, -21); c.lineTo(-2, -17); c.moveTo(7, -15); c.lineTo(6, -21); c.lineTo(2, -17); c.fill();
  c.fillStyle = bl; c.beginPath(); c.ellipse(0, -5, 5, 5.5, 0, 0, 7); c.fill();
  var lx = look || 0; c.fillStyle = '#FFFFFF'; c.beginPath(); c.arc(-3.4, -12.5, 3.4, 0, 7); c.arc(3.4, -12.5, 3.4, 0, 7); c.fill();
  var bk = m5_blinkAt(t, 5); c.fillStyle = m5_INK; c.beginPath(); c.ellipse(-3.4 + lx, -12.5, 1.6, 1.6 * bk, 0, 0, 7); c.ellipse(3.4 + lx, -12.5, 1.6, 1.6 * bk, 0, 0, 7); c.fill();
  c.fillStyle = '#F2A23A'; c.beginPath(); c.moveTo(-1.3, -10); c.lineTo(1.3, -10); c.lineTo(0, -7.6); c.fill();
  c.fillStyle = m5_BLUSH; c.beginPath(); c.ellipse(-5.6, -9.4, 1.7, 1, 0, 0, 7); c.ellipse(5.6, -9.4, 1.7, 1, 0, 0, 7); c.fill();
  c.fillStyle = '#F2A23A'; c.fillRect(-4, -0.6, 2.4, 1.6); c.fillRect(1.6, -0.6, 2.4, 1.6);
  c.restore(); }
// loaf or sitting cat. pose 'loaf' (lying, side view) or 'sit'; col = [fur, darker stripes or patch]
function m5_cat(c, x, y, s, dir, t, col, pose, tail, look, sleep, happy) {
  c.save(); c.translate(x, y); c.scale(s * dir, s); var f = col[0], d2 = col[1], e = m5_blinkAt(t, x * 0.01);
  c.strokeStyle = f; c.lineCap = 'round'; c.lineWidth = 3.4;
  if (pose === 'loaf') { c.beginPath(); c.moveTo(-11, -3); c.quadraticCurveTo(-18, 2 + tail * 3, -17 - tail * 2, 9 + tail * 6); c.stroke();
    c.fillStyle = f; c.beginPath(); c.ellipse(-2, -5.5, 12, 6.5, 0, 0, 7); c.fill(); if (d2) { c.fillStyle = d2; c.beginPath(); c.ellipse(-4, -9, 5, 2.4, 0.2, 0, 7); c.ellipse(-10, -6, 2.4, 3.4, 0.2, 0, 7); c.fill(); } }
  else { c.beginPath(); c.moveTo(-6, -3); c.quadraticCurveTo(-16 - tail * 2, -6, -12 + tail * 4, -18); c.stroke();
    c.fillStyle = f; c.beginPath(); c.ellipse(0, -9, 8, 10, 0, 0, 7); c.fill(); c.beginPath(); c.ellipse(-3, -1.5, 3.2, 2, 0, 0, 7); c.ellipse(4, -1.5, 3.2, 2, 0, 0, 7); c.fill(); if (d2) { c.fillStyle = d2; c.beginPath(); c.ellipse(-5, -10, 2.2, 4, 0.3, 0, 7); c.fill(); } }
  c.save(); c.translate(pose === 'loaf' ? 8 : 1, pose === 'loaf' ? -11 : -22); c.rotate(look || 0);
  c.fillStyle = f; c.beginPath(); c.moveTo(-7, -2); c.lineTo(-6, -11); c.lineTo(-1, -6); c.moveTo(1, -6); c.lineTo(6, -11); c.lineTo(7, -2); c.fill();
  c.fillStyle = '#FFB3C6'; c.beginPath(); c.moveTo(-5.4, -4.5); c.lineTo(-5.4, -8.6); c.lineTo(-3, -6); c.moveTo(5.4, -4.5); c.lineTo(5.4, -8.6); c.lineTo(3, -6); c.fill();
  c.fillStyle = f; c.beginPath(); c.ellipse(0, 0, 8, 7, 0, 0, 7); c.fill(); if (d2) { c.fillStyle = d2; c.beginPath(); c.moveTo(-2, -6.6); c.lineTo(0, -3); c.lineTo(2, -6.6); c.fill(); }
  if (sleep) { c.strokeStyle = m5_INK; c.lineWidth = 1; c.beginPath(); c.arc(-3, -0.5, 1.6, 0.2, Math.PI - 0.2); c.moveTo(4.6, -0.2); c.arc(3, -0.5, 1.6, 0.2, Math.PI - 0.2); c.stroke(); }
  else m5_eyes(c, 0, -0.6, 3, 1.25, happy ? 1 : e, happy);
  c.fillStyle = '#F28A9A'; c.beginPath(); c.moveTo(-1, 1.6); c.lineTo(1, 1.6); c.lineTo(0, 2.8); c.fill(); m5_cheeks(c, 0, 2.6, 4.6, 1.5);
  c.restore(); c.restore(); }
// a butterfly (day) or firefly (night) helper
function m5_fly(c, x, y, s, t, ph, col) { var fl = 0.25 + 0.75 * Math.abs(Math.sin(t * 8 + ph)); c.fillStyle = col; c.beginPath(); c.ellipse(x - 3.6 * fl * s, y - 1, 3.6 * fl * s, 4.6 * s, -0.3, 0, 7); c.ellipse(x + 3.6 * fl * s, y - 1, 3.6 * fl * s, 4.6 * s, 0.3, 0, 7); c.ellipse(x - 2.6 * fl * s, y + 3, 2.4 * fl * s, 3 * s, 0.4, 0, 7); c.ellipse(x + 2.6 * fl * s, y + 3, 2.4 * fl * s, 3 * s, -0.4, 0, 7); c.fill(); c.fillStyle = '#4A3A4A'; c.fillRect(x - 0.6 * s, y - 3.5 * s, 1.2 * s, 7 * s); }
// string of fairy lights between two points with a sag
function m5_lights(c, x0, y0, x1, y1, sag, n, t, cols, glowG, dk) { c.strokeStyle = dk ? 'rgba(30,24,60,0.7)' : 'rgba(90,80,120,0.55)'; c.lineWidth = 1; c.beginPath(); c.moveTo(x0, y0); c.quadraticCurveTo((x0 + x1) / 2, (y0 + y1) / 2 + sag * 2, x1, y1); c.stroke();
  for (var k = 1; k < n; k++) { var u = k / n, x = (1 - u) * (1 - u) * x0 + 2 * (1 - u) * u * (x0 + x1) / 2 + u * u * x1, y = (1 - u) * (1 - u) * y0 + 2 * (1 - u) * u * ((y0 + y1) / 2 + sag * 2) + u * u * y1 + 3, a = 0.6 + 0.4 * Math.sin(t * 1.7 + k * 1.9);
    if (glowG) m5_dot(c, glowG, x, y, 11, a * 0.8); c.fillStyle = cols[k % cols.length]; c.globalAlpha = dk ? 0.6 + 0.4 * a : 1; c.beginPath(); c.ellipse(x, y, 2.4, 3, 0, 0, 7); c.fill(); c.globalAlpha = 1; } }

function m5_cloud(c, x, y, s, t, k, col) { c.save(); c.translate(x, y); c.scale(s, s); c.fillStyle = col || '#FFFFFF'; c.globalAlpha = 0.95; c.beginPath(); c.arc(-22, 4, 14, 0, 7); c.arc(-4, -6, 20, 0, 7); c.arc(18, 2, 15, 0, 7); c.arc(0, 8, 14, 0, 7); c.fill(); c.globalAlpha = 1; m5_face(c, -2, 2, 16, false, m5_blinkAt(t, k + 3), false); c.restore(); }
function m5_goat(c, x, y, s, dir, t, chew, hop, happy) {
  c.save(); c.translate(x, y - hop); c.scale(s * dir, s); var b = '#FFF8EE', d = '#8A7060', hb = Math.sin(t * 6) * chew;
  c.strokeStyle = d; c.lineWidth = 2; c.lineCap = 'round'; c.beginPath(); [-8, -4, 5, 9].forEach(function (lx) { c.moveTo(lx, -6); c.lineTo(lx, 0); }); c.stroke();
  c.fillStyle = b; c.beginPath(); c.ellipse(0, -10, 13, 7.5, 0, 0, 7); c.fill(); c.beginPath(); c.moveTo(-12, -13); c.lineTo(-16, -17); c.lineTo(-13, -10); c.fill();
  c.save(); c.translate(12, -16 + hb); c.rotate(0.35 + hb * 0.05);
  c.strokeStyle = '#C9A27A'; c.lineWidth = 2.2; c.beginPath(); c.moveTo(-2, -5); c.quadraticCurveTo(-6, -12, -9, -9); c.moveTo(1, -5); c.quadraticCurveTo(-1, -13, -4, -12); c.stroke();
  c.fillStyle = b; c.beginPath(); c.ellipse(1, 0, 6, 5.4, 0, 0, 7); c.ellipse(5, 2.5, 4, 3.2, 0, 0, 7); c.fill(); c.beginPath(); c.ellipse(-5, -1, 4.5, 1.8, 0.5, 0, 7); c.fill();
  c.fillStyle = '#F4D6C0'; c.beginPath(); c.moveTo(4, 5); c.lineTo(6.5, 10); c.lineTo(8, 5); c.fill();
  m5_eyes(c, 2.2, -1, 0.001, 1.2, happy ? 1 : m5_blinkAt(t, x * 0.02), happy); c.fillStyle = m5_BLUSH; c.beginPath(); c.ellipse(3, 2, 2, 1.2, 0, 0, 7); c.fill(); c.restore();
  c.fillStyle = '#F2C24A'; c.beginPath(); c.arc(10, -7, 2.2, 0, 7); c.fill(); c.restore(); }
function m5_kid(c, x, y, s, t, hop, shirt) {
  c.save(); c.translate(x, y - hop); c.scale(s, s); c.strokeStyle = '#7A5A4A'; c.lineWidth = 2.2; c.lineCap = 'round';
  c.beginPath(); c.moveTo(-2.5, -9); c.lineTo(-3, 0); c.moveTo(2.5, -9); c.lineTo(3 + Math.sin(t * 3) * 0.8, 0); c.stroke();
  c.fillStyle = shirt; c.beginPath(); c.moveTo(-7, -9); c.lineTo(-3.5, -22); c.lineTo(3.5, -22); c.lineTo(7, -9); c.fill();
  c.strokeStyle = '#F5C9A8'; c.lineWidth = 2.4; c.beginPath(); c.moveTo(2.5, -20); c.lineTo(8, -30 + Math.sin(t * 1.3) * 1.5); c.moveTo(-2.5, -20); c.lineTo(-6, -14); c.stroke();
  c.fillStyle = '#F5C9A8'; c.beginPath(); c.arc(0, -28, 6.5, 0, 7); c.fill(); c.fillStyle = '#6A4A3A'; c.beginPath(); c.arc(0, -30, 6.6, Math.PI * 1.05, Math.PI * 1.95); c.fill(); c.beginPath(); c.arc(-4, -34, 3, 0, 7); c.fill();
  c.fillStyle = m5_INK; c.beginPath(); c.arc(-2.2, -27.5, 0.9, 0, 7); c.arc(2.6, -27.5, 0.9, 0, 7); c.fill(); m5_cheeks(c, 0.2, -25.2, 3.8, 1.3); c.restore();
  return [x + 8 * s, y - hop - 30 * s]; }
function m5_kite(c, x, y, s, t, cols, hand) {
  var rot = Math.sin(t * 0.9) * 0.15; c.strokeStyle = 'rgba(80,70,90,0.55)'; c.lineWidth = 0.8; c.beginPath(); c.moveTo(hand[0], hand[1]); c.quadraticCurveTo((hand[0] + x) / 2 + 20, (hand[1] + y) / 2 + 30, x, y + 10 * s); c.stroke();
  c.strokeStyle = 'rgba(80,70,90,0.5)'; c.beginPath(); c.moveTo(x, y + 13 * s); for (var k = 1; k <= 8; k++) c.lineTo(x + Math.sin(t * 3 + k * 0.8) * 5 * s - k * 1.5 * s, y + 13 * s + k * 6 * s); c.stroke();
  for (k = 1; k <= 3; k++) { var tx = x + Math.sin(t * 3 + k * 2.4) * 5 * s - k * 4 * s, ty = y + 13 * s + k * 16 * s; c.fillStyle = cols[k % cols.length]; c.beginPath(); c.moveTo(tx, ty); c.lineTo(tx - 4 * s, ty - 2.5 * s); c.lineTo(tx - 4 * s, ty + 2.5 * s); c.lineTo(tx + 4 * s, ty - 2.5 * s); c.lineTo(tx + 4 * s, ty + 2.5 * s); c.fill(); }
  c.save(); c.translate(x, y); c.rotate(rot); c.scale(s, s); var q = [[0, -13], [9, 0], [0, 13], [-9, 0]];
  for (k = 0; k < 4; k++) { c.fillStyle = cols[k % cols.length]; c.beginPath(); c.moveTo(0, 0); c.lineTo(q[k][0], q[k][1]); c.lineTo(q[(k + 1) % 4][0], q[(k + 1) % 4][1]); c.fill(); }
  m5_face(c, 0, -1, 6, false, m5_blinkAt(t, 7), true); c.restore(); }
function m5_dove(c, x, y, s, dir, t, peck) { c.save(); c.translate(x, y); c.scale(s * dir, s); c.fillStyle = '#FFFFFF'; c.beginPath(); c.ellipse(0, -5, 7, 5, -0.15, 0, 7); c.fill(); c.beginPath(); c.moveTo(-6, -6); c.lineTo(-11, -9); c.lineTo(-11, -4); c.fill();
  c.fillStyle = '#E8ECF4'; c.beginPath(); c.ellipse(-1, -5, 4, 2.6, -0.2, 0, 7); c.fill(); c.save(); c.translate(5, -9 + peck * 2); c.fillStyle = '#FFFFFF'; c.beginPath(); c.arc(0, 0, 3.6, 0, 7); c.fill(); c.fillStyle = '#F2A23A'; c.beginPath(); c.moveTo(3, -0.6); c.lineTo(6, 0.4); c.lineTo(3, 1); c.fill(); c.fillStyle = m5_INK; c.beginPath(); c.arc(1.2, -0.6, 0.8, 0, 7); c.fill(); c.fillStyle = m5_BLUSH; c.beginPath(); c.arc(1.4, 1.4, 1, 0, 7); c.fill(); c.restore(); c.restore(); }
function m5_dolphin(c, x, y, s, ang, col) { c.save(); c.translate(x, y); c.rotate(ang); c.scale(s, s); c.fillStyle = col; c.beginPath(); c.moveTo(16, 0); c.quadraticCurveTo(10, -8, -6, -6); c.quadraticCurveTo(-14, -4, -18, 0); c.lineTo(-24, -5); c.lineTo(-22, 1); c.lineTo(-25, 6); c.lineTo(-17, 3); c.quadraticCurveTo(-4, 6, 10, 4); c.quadraticCurveTo(18, 3, 20, 1); c.fill(); c.beginPath(); c.moveTo(-2, -6); c.lineTo(-7, -13); c.lineTo(3, -7); c.fill();
  c.fillStyle = '#EAF6FA'; c.beginPath(); c.moveTo(14, 3); c.quadraticCurveTo(0, 6, -10, 3); c.quadraticCurveTo(0, 2, 14, 2); c.fill(); c.fillStyle = m5_INK; c.beginPath(); c.arc(9, -2, 1.2, 0, 7); c.fill(); c.fillStyle = m5_BLUSH; c.beginPath(); c.arc(10, 1, 1.4, 0, 7); c.fill(); c.restore(); }

